import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './description-list.module.scss'

export interface DescriptionListProps {
  children: ReactNode
  className?: string
  columns?: 1 | 2 | 3
}

/**
 * Definition list.
 *
 * Columns follow the viewport, but each pair also measures its own cell: the
 * term and value sit side by side only when the column has room, and stack
 * otherwise. Tracks use `minmax(0, 1fr)` so a long value wraps instead of
 * pushing the list out of its card.
 */
export function DescriptionList({
  children,
  className,
  columns = 1,
}: DescriptionListProps) {
  return (
    <dl
      className={cx(
        styles.root,
        columns === 2 && styles.columns2,
        columns === 3 && styles.columns3,
        className,
      )}
    >
      {children}
    </dl>
  )
}

export interface DescriptionItemProps {
  term: ReactNode
  children: ReactNode
  className?: string
}

export function DescriptionItem({
  term,
  children,
  className,
}: DescriptionItemProps) {
  return (
    <div className={cx(styles.item, className)}>
      <dt className={styles.term}>{term}</dt>
      <dd className={styles.value}>{children}</dd>
    </div>
  )
}

@use 'styles' as vz;

.root {
  overflow: hidden;
  margin: 0;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
}

.item {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  container-type: inline-size;
  min-width: 0;
  padding: vz.space(4);
}

.item + .item {
  border-top: 1px solid vz.color('border');
}

.term {
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.value {
  min-width: 0;
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  overflow-wrap: break-word;
}

@container (min-width: 18rem) {
  .item {
    flex-direction: row;
    gap: vz.space(4);
  }

  .term {
    flex: none;
    width: 8rem;
  }

  .value {
    flex: 1;
  }
}

@include vz.up('sm') {
  .columns-2,
  .columns-3 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .columns-2 .item + .item,
  .columns-3 .item + .item {
    border-top: 0;
  }
}

@include vz.up('lg') {
  .columns-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
